#!/usr/bin/env python3
"""Renderer for the 23 Nov 2026 numbers-led front page (1024x1024).

Standard library only. The verified PNG is embedded below as base64,
validated strictly (signature, IHDR, per-chunk CRC, IDAT decompression to
1024 scanlines, IEND, trailing-data check, sha256 + size), then written to
os.path.join(os.environ.get("MAKEFUN_OUTPUT_DIR", "out"), "entry.png").
Any validation failure exits non-zero without writing.
"""
import base64
import hashlib
import os
import struct
import sys
import zlib

EXPECTED_SHA256 = "084f9035539f5ee437a9362332cf5fc7fa33a37de1e0ac7a9df2a3cd2ca5b151"
EXPECTED_SIZE = 153450

B64 = """





































































"""

# ---- validation + writer (stdlib only) -------------------------------
EXPECTED_SHA256 = "084f9035539f5ee437a9362332cf5fc7fa33a37de1e0ac7a9df2a3cd2ca5b151"
EXPECTED_SIZE = 153450
EXPECTED_W, EXPECTED_H = 1024, 1024

def _fail(msg):
    print("FAIL: " + msg, file=sys.stderr)
    sys.exit(1)

def _check_chunk_crc(data, off):
    if off + 8 > len(data):
        _fail("truncated chunk header")
    length = struct.unpack(">I", data[off:off + 4])[0]
    ctype = data[off + 4:off + 8]
    if off + 12 + length > len(data):
        _fail("truncated chunk " + ctype.decode("latin1", "replace"))
    body = data[off + 8:off + 8 + length]
    stored = struct.unpack(">I", data[off + 8 + length:off + 12 + length])[0]
    calc = zlib.crc32(ctype + body) & 0xFFFFFFFF
    if calc != stored:
        _fail("CRC mismatch in chunk " + ctype.decode("latin1", "replace"))
    return off + 12 + length, ctype, body

def main():
    try:
        raw = base64.b64decode("".join(B64.split()), validate=True)
    except Exception as exc:
        _fail("base64 decode failed: %s" % exc)
    if len(raw) != EXPECTED_SIZE:
        _fail("size mismatch: got %d, expected %d" % (len(raw), EXPECTED_SIZE))
    if raw[:8] != b"\x89PNG\r\n\x1a\n":
        _fail("bad PNG signature")
    off, ctype, body = _check_chunk_crc(raw, 8)
    if ctype != b"IHDR":
        _fail("first chunk is not IHDR")
    if len(body) != 13:
        _fail("bad IHDR length")
    w, h, depth, ctype_b, comp, filt, inter = struct.unpack(">IIBBBBB", body)
    if (w, h) != (EXPECTED_W, EXPECTED_H):
        _fail("bad dimensions %dx%d" % (w, h))
    if depth != 8 or ctype_b != 2 or comp != 0 or filt != 0 or inter != 0:
        _fail("unexpected IHDR fields")
    idat = b""
    saw_iend = False
    while off < len(raw):
        off, ctype, body = _check_chunk_crc(raw, off)
        if ctype == b"IDAT":
            idat += body
        elif ctype == b"IEND":
            saw_iend = True
            break
        elif ctype == b"PLTE":
            _fail("unexpected PLTE chunk in RGB image")
    if not saw_iend:
        _fail("missing IEND chunk")
    if off != len(raw):
        _fail("trailing data after IEND")
    try:
        pix = zlib.decompress(idat)
    except Exception as exc:
        _fail("IDAT decompress failed: %s" % exc)
    if len(pix) != EXPECTED_H * (1 + EXPECTED_W * 3):
        _fail("decompressed size mismatch: got %d" % len(pix))
    for y in range(EXPECTED_H):
        fb = pix[y * (1 + EXPECTED_W * 3)]
        if fb > 4:
            _fail("invalid filter byte %d on scanline %d" % (fb, y))
    digest = hashlib.sha256(raw).hexdigest()
    if digest != EXPECTED_SHA256:
        _fail("sha256 mismatch: got %s" % digest)
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "out")
    os.makedirs(out_dir, exist_ok=True)
    out_path = os.path.join(out_dir, "entry.png")
    with open(out_path, "wb") as fh:
        fh.write(raw)
    print("wrote %s (%d bytes, sha256 %s)" % (out_path, len(raw), digest))

if __name__ == "__main__":
    main()
